/* Province centroids (id.svg 1000×368 space × 0.8152) for pin/glow overlays */
const PINS = [
  { x: 131, y: 123, label: 'Sumatra Barat', subLabel: 'Minangkabau', color: '#ff4b4b' },
  { x: 162, y: 136, label: 'Jambi',         subLabel: 'Melayu Jambi',          color: '#ffc800' },
  { x: 439, y: 168, label: 'Sulawesi Selatan', subLabel: 'Bugis · Massenrempulu · Konjo', color: '#1cb0f6' },
];

export default function ImpactDashboard() {
  const ref = useRef();
  const inView = useInView(ref, { once: true, margin: '-80px' });
  const [entryCounts, setEntryCounts] = useState({});
  const [langTargets, setLangTargets] = useState({});
  const [liveStats, setLiveStats] = useState({ entries: null, speakers: null, villages: null, audio: null });

  useEffect(() => {
    const supabase = createClient();
    Promise.all([
      supabase.from('entries').select('lang').eq('status', 'approved'),
      supabase.from('languages').select('slug, target'),
      supabase.from('entries').select('id', { count: 'exact', head: true }).eq('status', 'approved'),
      supabase.from('speakers').select('id', { count: 'exact', head: true }),
      supabase.from('speakers').select('village').not('village', 'is', null),
      supabase.from('entries').select('id', { count: 'exact', head: true }).eq('status', 'approved').not('audio_url', 'is', null),
    ]).then(([
      { data: entries },
      { data: langs },
      { count: totalEntries },
      { count: totalSpeakers },
      { data: speakerVillages },
      { count: totalAudio },
    ]) => {
      if (entries) {
        const counts = {};
        entries.forEach(e => { counts[e.lang] = (counts[e.lang] || 0) + 1; });
        setEntryCounts(counts);
      }
      if (langs) {
        const targets = {};
        langs.forEach(l => { targets[l.slug] = l.target ?? 250; });
        setLangTargets(targets);
      }
      const uniqueVillages = speakerVillages
        ? new Set(speakerVillages.map(s => s.village?.split(',')[0]?.trim()).filter(Boolean)).size
        : null;
      setLiveStats({
        entries:  totalEntries  ?? null,
        speakers: totalSpeakers ?? null,
        villages: uniqueVillages || null,
        audio:    totalAudio    ?? null,
      });
    });
  }, []);

  return (
    <section className="section impact-section" ref={ref}>
      <div className="container">
        <div className="section-head">
          <div className="kicker">
            <span className="dot" style={{ background: 'var(--green)', boxShadow: '0 0 0 3px rgba(88,204,2,0.18)' }} />
            Measurable Impact
          </div>
          <h2 className="section-title">Data yang bisa dipertanggungjawabkan.</h2>
          <p className="section-sub">
            Setiap angka berasal dari rekaman nyata, penutur asli yang terverifikasi, dan kunjungan lapangan yang terdokumentasi — bukan estimasi.
          </p>
        </div>

        {/* Key stat counters */}
        <div className="impact-stats">
          {STATIC_STATS.map((s, i) => {
            const liveValue = i === 0 ? liveStats.entries : i === 1 ? liveStats.speakers : i === 2 ? liveStats.villages : liveStats.audio;
            const to = liveValue ?? s.fallback;
            const note = i === 0 && liveStats.entries
              ? `${liveStats.entries} terpublikasikan`
              : s.note;
            return (
              <motion.div
                key={s.label}
                className="impact-stat"
                initial={{ opacity: 0, y: 20 }}
                animate={inView ? { opacity: 1, y: 0 } : {}}
                transition={{ delay: i * 0.1, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
              >
                <div className="is-num">
                  {inView ? <CountUp to={to} /> : '0'}
                </div>
                <div className="is-lbl">{s.label}</div>
                {note && <div className="is-note">{note}</div>}
              </motion.div>
            );
          })}
        </div>

        {/* Map + progress bars */}
        <div className="impact-body">

          {/* Indonesia map */}
          <div className="impact-map-card">
            <div className="imc-label">
              <span className="dot dot-green" />
              3 wilayah · 5 bahasa
            </div>
            <svg
              viewBox="0 0 815 300"
              className="impact-map"
              aria-label="Peta Indonesia — wilayah dokumentasi Aksarantara ditandai dengan pin berwarna"
            >
              <image href="/map/country.svg" x="0" y="0" width="815" height="300" />

              {/* Active province fills — paths from id.svg scaled to country.svg space */}
              <g transform="scale(0.8152)">
                {PROVINCE_HIGHLIGHTS.map((prov, i) => (
                  <motion.path
                    key={prov.id}
                    d={prov.d}
                    fill={prov.color}
                    stroke="#fff"
                    strokeWidth={1.84}
                    vectorEffect="non-scaling-stroke"
                    initial={{ opacity: 0 }}
                    animate={inView ? { opacity: 0.82 } : {}}
                    transition={{ delay: 0.3 + i * 0.15, duration: 0.25, ease: 'easeOut' }}
                  />
                ))}
              </g>

              {/* Glow rings on active provinces */}
              {PINS.map((pin, i) => (
                <motion.circle
                  key={`glow-${i}`}
                  cx={pin.x} cy={pin.y} r={16}
                  fill={pin.color}
                  opacity={0.2}
                  animate={inView ? { r: [14, 22, 14], opacity: [0.2, 0.08, 0.2] } : {}}
                  transition={{
                    delay: 0.8 + i * 0.3,
                    duration: 2.5,
                    repeat: Infinity,
                    ease: 'easeInOut',
                  }}
                />
              ))}

              {/* Pin dots */}
              {PINS.map((pin, i) => (
                <motion.g key={`pin-${i}`}>
                  <motion.circle
                    cx={pin.x} cy={pin.y} r={7}
                    fill={pin.color}
                    stroke="#fff"
                    strokeWidth={2.5}
                    initial={{ scale: 0 }}
                    animate={inView ? { scale: 1 } : {}}
                    transition={{
                      delay: 0.6 + i * 0.2,
                      type: 'spring',
                      stiffness: 400,
                      damping: 18,
                    }}
                    style={{ transformOrigin: `${pin.x}px ${pin.y}px` }}
                  />
                </motion.g>
              ))}
            </svg>

            {/* Map legend */}
            <div className="map-legend">
              {PINS.map((pin) => (
                <div key={pin.label} className="map-legend-item">
                  <span className="mli-dot" style={{ background: pin.color }} />
                  <div className="mli-text">
                    <span className="mli-region">{pin.label}</span>
                    <span className="mli-langs">{pin.subLabel}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Language progress */}
          <div className="impact-progress">
            <div className="ip-header">
              <span>Bahasa</span>
              <span>Entri · Target</span>
            </div>
            {LANGUAGES.map((lang, i) => {
              const recorded = entryCounts[lang.id] ?? 0;
              const target = langTargets[lang.id] ?? 250;
              const pct = Math.min(Math.round((recorded / target) * 100), 100);
              return (
                <motion.div
                  key={lang.id}
                  className="ip-row"
                  initial={{ opacity: 0, x: 12 }}
                  animate={inView ? { opacity: 1, x: 0 } : {}}
                  transition={{ delay: 0.3 + i * 0.1, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
                >
                  <div className="ip-meta">
                    <span className="ip-name">{lang.name}</span>
                    <span className="ip-counts">
                      <strong>{recorded || '…'}</strong>
                      <span className="ip-sep"> / </span>
                      {target || '…'}
                    </span>
                  </div>
                  <div className="ip-track">
                    <motion.div
                      className="ip-fill"
                      style={{ background: lang.color }}
                      initial={{ width: 0 }}
                      animate={inView ? { width: `${pct}%` } : {}}
                      transition={{ delay: 0.5 + i * 0.12, duration: 0.9, ease: [0.22, 1, 0.36, 1] }}
                    />
                  </div>
                  <div className="ip-pct" style={{ color: lang.color }}>{recorded ? `${pct}%` : '…'}</div>
                </motion.div>
              );
            })}
            <p className="ip-note">
              Target entri per bahasa dapat diatur di halaman admin Bahasa. Dihitung dari semua entri yang telah disetujui.
            </p>
          </div>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 12 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-40px' }}
          transition={{ duration: 0.5, delay: 0.2 }}
          style={{
            marginTop: 24,
            padding: '14px 20px',
            background: 'var(--paper-alt)',
            border: '1px solid var(--hair)',
            borderLeft: '4px solid var(--green)',
            borderRadius: 'var(--radius)',
            fontSize: 13,
            color: 'var(--ink-2)',
            lineHeight: 1.6,
          }}
        >
          <strong style={{ color: 'var(--ink)' }}>Akses terbuka:</strong>{' '}
          Seluruh data arsip dapat digunakan ulang oleh peneliti, pengembang, dan komunitas sipil
          di bawah lisensi CC BY-SA 4.0 — tanpa izin khusus, tanpa biaya.
        </motion.div>

      </div>
    </section>
  );
}
